/**
 * Mobile navigation drawer.
 *
 * On narrow screens app.css hides the rail entirely and falls back to a
 * horizontal strip of all 77 destinations, which is not navigable. This
 * turns the real rail into an off-canvas drawer instead.
 *
 * The menu button and backdrop are created here rather than in the markup,
 * because web/index.html is generated by scripts/build-frontend.js and would
 * lose any hand-edit on the next rebuild.
 */
(function () {
  'use strict';

  var MOBILE = '(max-width: 1024px)';

  function ready(fn) {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', fn);
    } else {
      fn();
    }
  }

  ready(function () {
    var bar = document.querySelector('.top');
    var rail = document.querySelector('.rail');
    if (!bar || !rail) return;

    // ---- menu button, first thing in the top bar --------------------
    var toggle = document.createElement('button');
    toggle.id = 'nav-toggle';
    toggle.type = 'button';
    toggle.setAttribute('aria-label', 'Open navigation');
    toggle.setAttribute('aria-expanded', 'false');
    toggle.setAttribute('aria-controls', 'rail-nav');
    toggle.innerHTML =
      '<svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" ' +
      'stroke-width="1.8" stroke-linecap="round"><path d="M3 5.5h14M3 10h14M3 14.5h14"/></svg>';
    bar.insertBefore(toggle, bar.firstChild);

    rail.id = rail.id || 'rail-nav';

    // ---- backdrop ----------------------------------------------------
    var backdrop = document.createElement('div');
    backdrop.id = 'nav-backdrop';
    document.body.appendChild(backdrop);

    function isMobile() {
      return window.matchMedia(MOBILE).matches;
    }

    function open() {
      document.body.classList.add('nav-open');
      toggle.setAttribute('aria-expanded', 'true');
      toggle.setAttribute('aria-label', 'Close navigation');
    }

    function close() {
      document.body.classList.remove('nav-open');
      toggle.setAttribute('aria-expanded', 'false');
      toggle.setAttribute('aria-label', 'Open navigation');
    }

    function isOpen() {
      return document.body.classList.contains('nav-open');
    }

    toggle.addEventListener('click', function (e) {
      e.stopPropagation();
      if (isOpen()) close(); else open();
    });

    backdrop.addEventListener('click', close);

    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && isOpen()) close();
    });

    // Close after picking a destination, but not when expanding a section
    // header - those just reveal their children inside the drawer.
    rail.addEventListener('click', function (e) {
      if (!isMobile() || !isOpen()) return;
      if (e.target.closest('.sechd')) return;
      if (e.target.closest('[data-go]')) close();
    }, true);

    // Rotating to landscape / resizing to desktop must not strand the
    // drawer open with the body still locked.
    window.matchMedia(MOBILE).addEventListener('change', function (ev) {
      if (!ev.matches) close();
    });

    // ---- swipe to close ---------------------------------------------
    var startX = null;
    var startY = null;
    rail.addEventListener('touchstart', function (e) {
      if (e.touches.length !== 1) return;
      startX = e.touches[0].clientX;
      startY = e.touches[0].clientY;
    }, { passive: true });

    rail.addEventListener('touchend', function (e) {
      if (startX === null) return;
      var t = e.changedTouches[0];
      var dx = t.clientX - startX;
      var dy = Math.abs(t.clientY - startY);
      // a clear leftward swipe, not a vertical scroll
      if (dx < -55 && dy < 45) close();
      startX = startY = null;
    }, { passive: true });
  });
})();
